import React, { useState, useEffect } from 'react';
import { ChevronDown, Check, MapPin } from 'lucide-react';

const sampleAddresses = [
  {
    id: 1,
    name: 'Gourav Gupta',
    phone: '+91 98765 43210',
    address: '123, Tech Park, Sector 5, Bangalore, Karnataka - 560001',
    type: 'Work'
  },
  {
    id: 2,
    name: 'Gourav Gupta',
    phone: '+91 98765 43210',
    address: '45/A, Green Avenue, Indiranagar, Bangalore, Karnataka - 560038',
    type: 'Home'
  },
  {
    id: 3,
    name: 'Gourav Gupta',
    phone: '+91 98765 43210',
    address: '789, Lake View Apartments, Hebbal, Bangalore, Karnataka - 560024',
    type: 'Other'
  }
];

const OrderSummary = ({
  deliveryAddress,
  couponCode,
  onCouponChange,
  onApplyCoupon,
  totals,
  onOrderNow,
  onAddNewAddress,
  onChangeAddress // Keeping this prop if parent needs to know, but we'll handle selection locally for now
}) => {
  const [currentAddress, setCurrentAddress] = useState(deliveryAddress);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);

  // Sync with prop if it changes initially
  useEffect(() => {
    if (deliveryAddress && !currentAddress) {
      setCurrentAddress(deliveryAddress);
    }
  }, [deliveryAddress]);

  const handleAddressSelect = (address) => {
    setCurrentAddress(address);
    setIsDropdownOpen(false);
    if (onChangeAddress) {
      onChangeAddress(address);
    }
  };

  return (
    <div className="sticky top-32 space-y-3">
      {/* Delivery Address */}
      <div style={{
        backgroundColor: '#FFFFFF',
        borderRadius: '12px',
        padding: '16px',
        boxShadow: '0 1px 2px rgba(0, 0, 0, 0.06)',
        border: '1px solid #64E5B8',
        marginBottom: '5px'
      }}>
        <div className="flex justify-between items-center mb-3">
          <h3
            style={{
              fontFamily: 'Gyrotrope',
              fontSize: '16px',
              fontWeight: 600,
              color: '#34B485',
              letterSpacing: '-0.01em',
              marginBottom: '8px'
            }}
          >
            Delivery Address
          </h3>
          {currentAddress?.type && (
            <span className="text-[10px] font-semibold px-2 py-0.5 rounded bg-gray-100 text-gray-600 border border-gray-200">
              {currentAddress.type}
            </span>
          )}
        </div>

        <div
          style={{
            fontFamily: 'Gyrotrope',
            fontSize: '12px',
            fontWeight: 400,
            color: '#374151',
            lineHeight: '1.5',
            marginBottom: '12px'
          }}
        >
          <div style={{ fontWeight: 600, marginBottom: '2px', color: '#000000' }}>
            {currentAddress?.name || 'Select Address'} - {currentAddress?.phone}
          </div>
          <div className="line-clamp-2">{currentAddress?.address}</div>
        </div>

        <div className="flex gap-2 relative">
          <button
            onClick={onAddNewAddress}
            className="flex-1 transition-colors cursor-pointer hover:opacity-90"
            style={{
              fontFamily: 'Gyrotrope',
              fontSize: '11px',
              fontWeight: 600,
              backgroundColor: '#A5E8DC',
              color: '#000000',
              border: 'none',
              borderRadius: '8px',
              padding: '6px 10px',
              height: '30px'
            }}
          >
            + Add New Address
          </button>

          <div className="relative">
            <button
              onClick={() => setIsDropdownOpen(!isDropdownOpen)}
              className="transition-colors cursor-pointer hover:bg-gray-50 flex items-center gap-1"
              style={{
                fontFamily: 'Gyrotrope',
                fontSize: '11px',
                fontWeight: 600,
                color: '#000000',
                border: '1px solid #D1D5DB',
                borderRadius: '8px',
                padding: '6px 10px',
                height: '30px',
                backgroundColor: 'transparent'
              }}
            >
              Change Address
              <ChevronDown size={14} className={`transition-transform duration-200 ${isDropdownOpen ? 'rotate-180' : ''}`} />
            </button>

            {isDropdownOpen && (
              <div
                className="absolute right-0 top-full mt-2 w-72 bg-white rounded-xl shadow-xl border border-gray-100 z-50 overflow-hidden"
                style={{ animation: 'fadeIn 0.2s ease-out' }}
              >
                <div className="p-2 bg-gray-50 border-b border-gray-100">
                  <span className="text-xs font-semibold text-gray-500 px-2">Select Delivery Location</span>
                </div>
                <div className="max-h-64 overflow-y-auto py-1">
                  {sampleAddresses.map((addr) => (
                    <button
                      key={addr.id}
                      onClick={() => handleAddressSelect(addr)}
                      className="w-full text-left px-4 py-3 hover:bg-gray-50 transition-colors border-b border-gray-50 last:border-0 group relative"
                    >
                      <div className="flex items-start gap-3">
                        <div className={`mt-0.5 p-1.5 rounded-full ${currentAddress?.id === addr.id ? 'bg-emerald-100 text-emerald-600' : 'bg-gray-100 text-gray-400'}`}>
                          <MapPin size={14} />
                        </div>
                        <div className="flex-1">
                          <div className="flex justify-between items-center mb-0.5">
                            <span className="font-semibold text-xs text-gray-900">{addr.type}</span>
                            {currentAddress?.id === addr.id && (
                              <Check size={14} className="text-emerald-600" />
                            )}
                          </div>
                          <p className="text-xs text-gray-600 line-clamp-2 leading-relaxed">
                            {addr.address}
                          </p>
                        </div>
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Apply Coupon */}
      <div className='bg-orange-100' style={{
        borderRadius: '12px',
        padding: '16px',
        boxShadow: '0 1px 2px rgba(0, 0, 0, 0.06)',
        border: '1px solid #F97316',
        marginBottom: '5px'
      }}>
        <h3
          style={{
            fontFamily: 'Gyrotrope',
            fontSize: '16px',
            fontWeight: 600,
            color: '#F97316',
            marginBottom: '10px',
            letterSpacing: '-0.01em'
          }}
        >
          Apply Coupon
        </h3>
        <div className="flex gap-2">
          <input
            type="text"
            value={couponCode}
            onChange={onCouponChange}
            placeholder="Enter coupon code"
            className="flex-1 focus:outline-none focus:ring-2 focus:ring-orange-400"
            style={{
              fontFamily: 'Gyrotrope',
              fontSize: '11px',
              padding: '6px 10px',
              border: '1px solid #F97316',
              borderRadius: '8px',
              height: '30px',
              background: '#FFFFFF',
            }}
          />
          <button
            onClick={onApplyCoupon}
            className="transition-colors cursor-pointer hover:opacity-90"
            style={{
              fontFamily: 'Gyrotrope',
              fontSize: '11px',
              fontWeight: 600,
              backgroundColor: '#FFFFFF',
              borderRadius: '8px',
              padding: '6px 10px',
              height: '30px',
              border: '1px solid #F97316',
              color: 'black',
            }}
          >
            Apply
          </button>
        </div>
      </div>

      {/* Payment Breakdown */}
      <div style={{
        backgroundColor: '#FFFFFF',
        borderRadius: '12px',
        padding: '16px',
        boxShadow: '0 1px 2px rgba(0, 0, 0, 0.06)',
        border: '1px solid #64E5B8'
      }}>
        <h3
          style={{
            fontFamily: 'Gyrotrope',
            fontSize: '16px',
            fontWeight: 600,
            color: '#34B485',
            marginBottom: '12px',
            letterSpacing: '-0.01em'
          }}
        >
          Payment Breakdown
        </h3>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <div className="flex justify-between">
            <span
              style={{
                fontFamily: 'Gyrotrope',
                fontSize: '11px',
                fontWeight: 400,
                color: '#6B7280'
              }}
            >
              Total Cart Value
            </span>
            <span
              style={{
                fontFamily: 'Gyrotrope',
                fontSize: '11px',
                fontWeight: 600,
                color: '#000000'
              }}
            >
              ₹{totals.totalCartValue}
            </span>
          </div>
          <div className="flex justify-between">
            <span
              style={{
                fontFamily: 'Gyrotrope',
                fontSize: '11px',
                fontWeight: 400,
                color: '#6B7280'
              }}
            >
              Discount
            </span>
            <span
              style={{
                fontFamily: 'Gyrotrope',
                fontSize: '11px',
                fontWeight: 600,
                color: '#10B981'
              }}
            >
              -₹{totals.discount}
            </span>
          </div>
          <div className="flex justify-between">
            <span
              style={{
                fontFamily: 'Gyrotrope',
                fontSize: '11px',
                fontWeight: 400,
                color: '#6B7280'
              }}
            >
              Coupon
            </span>
            <span
              style={{
                fontFamily: 'Gyrotrope',
                fontSize: '11px',
                fontWeight: 600,
                color: '#10B981'
              }}
            >
              -₹{totals.coupon}
            </span>
          </div>
          <div className="flex justify-between">
            <span
              style={{
                fontFamily: 'Gyrotrope',
                fontSize: '11px',
                fontWeight: 400,
                color: '#6B7280'
              }}
            >
              GST
            </span>
            <span
              style={{
                fontFamily: 'Gyrotrope',
                fontSize: '11px',
                fontWeight: 600,
                color: '#000000'
              }}
            >
              +₹{totals.gst}
            </span>
          </div>
          <div className="flex justify-between">
            <span
              style={{
                fontFamily: 'Gyrotrope',
                fontSize: '11px',
                fontWeight: 400,
                color: '#6B7280'
              }}
            >
              Delivery Charges
            </span>
            <span
              style={{
                fontFamily: 'Gyrotrope',
                fontSize: '11px',
                fontWeight: 600,
                color: '#000000'
              }}
            >
              +₹{totals.deliveryCharges}
            </span>
          </div>
          <div style={{ borderTop: '1px solid #E5E7EB', paddingTop: '10px', marginTop: '10px' }}>
            <div className="flex justify-between">
              <span
                style={{
                  fontFamily: 'Gyrotrope',
                  fontSize: '13px',
                  fontWeight: 700,
                  color: '#000000'
                }}
              >
                Total
              </span>
              <span
                style={{
                  fontFamily: 'Gyrotrope',
                  fontSize: '13px',
                  fontWeight: 700,
                  color: '#000000'
                }}
              >
                ₹{totals.total}
              </span>
            </div>
          </div>
        </div>

        {/* Order Now Button */}
        <button
          onClick={onOrderNow}
          className="w-full transition-all duration-200 hover:opacity-90 cursor-pointer"
          style={{
            fontFamily: 'Gyrotrope',
            fontSize: '14px',
            fontWeight: 600,
            backgroundColor: '#FF7A59',
            color: '#FFFFFF',
            border: 'none',
            borderRadius: '10px',
            padding: '8px',
            marginTop: '16px',
            boxShadow: '0 2px 4px rgba(0, 0, 0, 0.08)'
          }}
        >
          Order Now
        </button>
      </div>
    </div>
  );
};

export default OrderSummary;

import React from 'react';
/* eslint-disable-next-line no-unused-vars */
import { motion as Motion } from 'framer-motion';
import { Heart } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import CartIcon from '../../../../assets/icons/Cart.png';

const PharmacyProductCard = ({
  id,
  name,
  price,
  originalPrice,
  discount,
  quantity,
  unit = 'piece',
  imageUrl,
  onAddToCart = () => { },
  onCardClick = () => { },
  className = ''
}) => {
  const navigate = useNavigate();

  const discountPercentage = originalPrice && price
    ? Math.round(((originalPrice - price) / originalPrice) * 100)
    : discount;

  const handleAddToCart = (e) => {
    e.stopPropagation();
    onAddToCart({ id, name, price, quantity, unit });
  };

  const handleCardClick = () => {
    navigate(`/product/${id}`);
    onCardClick({ id, name, price, quantity, unit });
  };

  return (
    <Motion.div
      className={`bg-transparent overflow-hidden rounded-lg cursor-pointer transition-all duration-300 hover:shadow-lg w-full ${className}`}
      style={{ maxWidth: '320px', padding: '10px' }}
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      whileHover={{ y: -2 }}
      whileTap={{ scale: 0.98 }}
      onClick={handleCardClick}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          handleCardClick();
        }
      }}
      aria-label={`${name} - ${quantity} ${unit} - ₹${price}`}
    >
      {/* Product Image */}
      <div className="relative overflow-hidden aspect-4/3 bg-linear-to-br from-sky-100 to-sky-200">
        <img
          src={imageUrl}
          alt={name}
          className="object-cover w-full h-full px-2 py-2"
          loading="lazy"
        />
        {/* Dark shadow gradient on upper half */}
        <div
          className="absolute top-0 left-0 right-0 pointer-events-none"
          style={{
            height: '50%',
            background: 'linear-gradient(to bottom, rgba(0,0,0,0.15), transparent)'
          }}
        />
      </div>

      {/* Product Info */}
      <div className="relative pt-2 translate-y-1/8" >
        {/* Product Name */}
        <h3 className="flex items-center justify-start text-[14px] font-semibold leading-tight text-left text-gray-900 min-h-8">
          {name}
        </h3>

        {/* Price and Discount Row */}
        <div className="flex items-center gap-1 sm:gap-1 mb-2 pr-8 sm:pr-0">
          <span className="text-[10px] sm:text-[12px] font-bold text-gray-900" title={`₹${price}`}>
            ₹{price}
          </span>
          <span className="text-[8px] sm:text-[10px] text-gray-900 font-medium">
            /{unit}
          </span>
          {discountPercentage > 0 && (
            <span className="text-[6px] sm:text-[8px] font-medium text-green-600 truncate">
              ({discountPercentage}% off)
            </span>
          )}
        </div>

        {/* Cart Icon - Positioned absolutely */}
        <button
          onClick={handleAddToCart}
          className="absolute flex items-center justify-center transition-all duration-200 -translate-y-1/2 rounded-full shadow-md cursor-pointer right-0 top-1/2 hover:scale-110 focus:outline-none w-7 h-7 sm:w-[35px] sm:h-[35px]"
          aria-label={`Add ${name} to cart`}
          style={{
            backgroundColor: '#f5f5f5',
            border: '1px solid #e8e8e8',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center'
          }}
        >
          <img
            src={CartIcon}
            alt="Add to Cart"
            style={{
              width: '15px',
              height: '15px',
              objectFit: 'contain'
            }}
          />
        </button>
      </div>
    </Motion.div>
  );
};


export default PharmacyProductCard;

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

const BannerSection = () => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isHovered, setIsHovered] = useState(false);
  const intervalRef = useRef(null);

  const banners = [
    {
      id: 1,
      image: '/src/assets/images/Rectangle 10.png',
      alt: 'Health & Wellness Banner',
      title: 'Health & Wellness',
      bgColor: 'bg-emerald-300',
      link: '/health-wellness'
    },
    {
      id: 2,
      image: '/src/assets/images/Rectangle 11.png',
      alt: 'Medical Equipment Banner',
      title: 'Medical Equipment',
      bgColor: 'bg-red-800',
      link: '/medical-equipment'
    },
    {
      id: 3,
      image: '/src/assets/images/Rectangle 12.png',
      alt: 'Prescription Medicines Banner',
      title: 'Prescription Medicines',
      bgColor: 'bg-cyan-300',
      link: '/prescription-medicines'
    },
    {
      id: 4,
      image: '/src/assets/images/Rectangle 13.png',
      alt: 'Personal Care Banner',
      title: 'Personal Care',
      bgColor: 'bg-orange-400',
      link: '/personal-care'
    }
  ];

  const startAutoSlide = () => {
    if (intervalRef.current) clearInterval(intervalRef.current);

    intervalRef.current = setInterval(() => {
      if (!isHovered) {
        setCurrentIndex((prevIndex) => (prevIndex + 1) % banners.length);
      }
    }, 3000); // Change slide every 3 seconds
  };

  const stopAutoSlide = () => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
    }
  };

  useEffect(() => {
    startAutoSlide();
    return () => stopAutoSlide();
  }, [isHovered]);

  const handleBannerClick = (link) => {
    console.log(`Navigate to: ${link}`);
    // Add navigation logic here
  };

  const goToSlide = (index) => {
    setCurrentIndex(index);
  };

  const goToPrevious = () => {
    setCurrentIndex((prevIndex) => (prevIndex - 1 + banners.length) % banners.length);
  };

  const goToNext = () => {
    setCurrentIndex((prevIndex) => (prevIndex + 1) % banners.length);
  };

  return (
    <section className="w-full py-6 lg:py-8 bg-white mb-6 flex justify-center items-center" style={{ width: '100%', marginBottom: '3rem' }}>
      <div className="w-full max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Mobile Carousel - Single row, one at a time */}
        <div className="sm:hidden">
          <div
            className="relative overflow-hidden rounded-2xl"
            onMouseEnter={() => setIsHovered(true)}
            onMouseLeave={() => setIsHovered(false)}
          >
            {/* Banner Container */}
            <div className="flex transition-transform duration-500 ease-in-out"
              style={{ transform: `translateX(-${currentIndex * 100}%)` }}>
              {banners.map((banner) => (
                <div key={banner.id} className="w-full flex-shrink-0">
                  <Motion.div
                    className="group cursor-pointer w-full"
                    onClick={() => handleBannerClick(banner.link)}
                    role="button"
                    tabIndex={0}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        handleBannerClick(banner.link);
                      }
                    }}
                    aria-label={`Navigate to ${banner.title}`}
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                  >
                    {/* Banner Card */}
                    <div className="relative overflow-hidden rounded-2xl shadow-lg hover:shadow-xl transition-all duration-300 w-full mx-auto">
                      {/* Background Image */}
                      <div className="aspect-video relative w-full">
                        <img
                          src={banner.image}
                          alt={banner.alt}
                          className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
                          loading="lazy"
                        />

                        {/* Overlay for better text readability */}
                        <div className="absolute inset-0 bg-black/20 group-hover:bg-black/30 transition-colors duration-300" />

                        {/* Content Overlay */}
                        <div className="absolute inset-0 flex items-center justify-center">
                          <div className="text-center text-white">
                            <h3 className="text-lg font-bold mb-2 drop-shadow-lg">
                              {banner.title}
                            </h3>
                            <div className="w-12 h-0.5 bg-white mx-auto opacity-80 group-hover:opacity-100 transition-opacity duration-300" />
                          </div>
                        </div>

                        {/* Hover Effect Border */}
                        <div className="absolute inset-0 border-2 border-transparent group-hover:border-white/50 rounded-2xl transition-colors duration-300" />
                      </div>

                      {/* Fallback Background Color (if image fails to load) */}
                      <div className={`absolute inset-0 ${banner.bgColor} -z-10`} />
                    </div>
                  </Motion.div>
                </div>
              ))}
            </div>

            {/* Navigation Arrows */}
            <button
              onClick={goToPrevious}
              className="absolute left-2 top-1/2 transform -translate-y-1/2 bg-white/80 hover:bg-white text-gray-800 p-2 rounded-full shadow-lg transition-all duration-200 z-10"
              aria-label="Previous banner"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
              </svg>
            </button>

            <button
              onClick={goToNext}
              className="absolute right-2 top-1/2 transform -translate-y-1/2 bg-white/80 hover:bg-white text-gray-800 p-2 rounded-full shadow-lg transition-all duration-200 z-10"
              aria-label="Next banner"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
              </svg>
            </button>

            {/* Dots Indicator */}
            <div className="absolute bottom-4 left-1/2 transform -translate-x-1/2 flex space-x-2 z-10">
              {banners.map((_, index) => (
                <button
                  key={index}
                  onClick={() => goToSlide(index)}
                  className={`w-2 h-2 rounded-full transition-all duration-200 ${index === currentIndex ? 'bg-white' : 'bg-white/50'
                    }`}
                  aria-label={`Go to banner ${index + 1}`}
                />
              ))}
            </div>
          </div>
        </div>

        {/* Desktop Grid - Original layout */}
        <div className="hidden sm:block">
          {/* Banner Grid - Compact Layout */}
          <div className="w-full flex justify-center">
            <Motion.div
              className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 sm:gap-6 lg:gap-8 w-full max-w-7xl justify-items-center"
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true, margin: "-30px" }}
              variants={{
                hidden: { opacity: 0 },
                visible: {
                  opacity: 1,
                  transition: {
                    staggerChildren: 0.1,
                    delayChildren: 0.2
                  }
                }
              }}
            >
              {banners.map((banner, index) => (
                <Motion.div
                  key={banner.id}
                  variants={{
                    hidden: { opacity: 0, y: 30 },
                    visible: {
                      opacity: 1,
                      y: 0,
                      transition: {
                        duration: 0.6,
                        ease: "easeOut"
                      }
                    }
                  }}
                  whileHover={{
                    scale: 1.05,
                    y: -8,
                    transition: { duration: 0.3, ease: "easeOut" }
                  }}
                  whileTap={{ scale: 0.98 }}
                  className="group cursor-pointer w-full flex justify-center"
                  onClick={() => handleBannerClick(banner.link)}
                  role="button"
                  tabIndex={0}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      e.preventDefault();
                      handleBannerClick(banner.link);
                    }
                  }}
                  aria-label={`Navigate to ${banner.title}`}
                >
                  {/* Banner Card - Centered */}
                  <div className="relative overflow-hidden rounded-2xl shadow-lg hover:shadow-xl transition-all duration-300 w-full max-w-sm">
                    {/* Background Image */}
                    <div className="aspect-4/3 relative w-full">
                      <img
                        src={banner.image}
                        alt={banner.alt}
                        className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
                        loading="lazy"
                      />

                      {/* Overlay for better text readability */}
                      <div className="absolute inset-0 bg-black/20 group-hover:bg-black/30 transition-colors duration-300" />

                      {/* Content Overlay */}
                      <div className="absolute inset-0 flex items-center justify-center">
